#!/usr/bin/env node
/**
 * Transfer real October 18 media into the isolated V2 source branch.
 * Source files were generated by browser capture Actions in their product repositories,
 * verified against the original GitHub artifact SHA-256, and stored on REVIEW branches.
 * Nothing is downloaded from a client source, private user record, or inferred URL.
 * Run manually: node scripts/sync-portfolio-review-media.mjs
 */
import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
import {mkdirSync,readFileSync,writeFileSync} from 'node:fs';
import {join} from 'node:path';

const S=[
 {id:'chatx',repo:'chat',sha:'080cb53e1ff93f85bc44ceef1b20f699340b56a9',
  files:['01-home-desktop.png','02-chats-desktop.png','03-tasks-desktop.png','05-project-gantt-desktop.png','chatx-product-tour-27s.mp4']},
 {id:'sostoyanie',repo:'promomed',sha:'42ad14b9e356a10a39dea4c983783affc7d7a05c',
  files:['iphone-15-today.png','iphone-15-media.png','iphone-15-events.png','iphone-journey-25s.mp4']}
];
const root='assets/portfolio-reviewed';
const retrieved=[];
const branch='portfolio/media-captures-20261020';
async function get(url){
 const res=await fetch(url,{signal:AbortSignal.timeout(25000),redirect:'follow'});
 if(!res.ok)throw Error('Source missing HTTP '+res.status+' '+url);
 return Buffer.from(await res.arrayBuffer());
}
for(const p of S){
 const dir=join(root,p.id);
 const base='https://raw.githubusercontent.com/PetrFedin/'+p.repo+'/'+branch+'/public/portfolio-v2/20261018/';
 const manifest=JSON.parse((await get(base+'capture-manifest.json')).toString('utf8'));
 assert.equal(manifest.source_sha,p.sha,'Wrong source commit for '+p.id);
 assert.equal(manifest.project,p.id);
 assert.equal(manifest.production_admitted,false,'Demo may not claim production');
 assert.ok(['isolated-demonstration','independent-public-preview'].includes(manifest.source_kind));
 const allowed=new Map(manifest.files.map(x=>[x.name,x.sha256]));
 assert.equal(allowed.size,manifest.files.length,'Duplicate asset in manifest');
 const files=[];
 for(const file of p.files){
  assert.match(file,/^[a-z0-9][a-z0-9_.-]+\.(png|mp4)$/i);
  assert.ok(allowed.has(file),'Manifest does not authorize '+file);
  const raw=await get(base+file);
  assert.ok(raw.length>3000&&raw.length<4_000_000,'Suspicious media size: '+file);
  const hash=createHash('sha256').update(raw).digest('hex');
  assert.equal(hash,allowed.get(file),'SHA-256 source mismatch for '+p.id+'/'+file);
  if(file.endsWith('.png'))assert.ok(raw.subarray(0,8).equals(Buffer.from('89504e470d0a1a0a','hex')),'Not PNG '+file);
  else assert.equal(raw.subarray(4,8).toString('ascii'),'ftyp','Not MP4 '+file);
  files.push({name:file,sha256:hash,bytes:raw.length,raw});
 }
 mkdirSync(dir,{recursive:true});
 for(const f of files)writeFileSync(join(dir,f.name),f.raw);
 retrieved.push({
  id:p.id,source_repository:'PetrFedin/'+p.repo,source_sha:p.sha,
  provenance:manifest.source_kind,date:'2026-10-18',environment:'browser evidence only',
  production_admitted:false,
  files:files.map(({raw,...other})=>other)
 });
}
const src='assets/content.js';
let text=readFileSync(src,'utf8');
const targets=[
 ["video: '/assets/video/chatx.webm',","video: '/assets/portfolio-reviewed/chatx/chatx-product-tour-27s.mp4',"],
 ["shots: ['/assets/shots/chatx-1.webp', '/assets/shots/chatx-2.webp', '/assets/shots/chatx-3.webp'],","shots: ['/assets/portfolio-reviewed/chatx/01-home-desktop.png', '/assets/portfolio-reviewed/chatx/02-chats-desktop.png', '/assets/portfolio-reviewed/chatx/03-tasks-desktop.png', '/assets/portfolio-reviewed/chatx/05-project-gantt-desktop.png'],"],
 ["shots: ['/assets/shots/promomed-home.jpg', '/assets/shots/promomed-events.jpg'],","video: '/assets/portfolio-reviewed/sostoyanie/iphone-journey-25s.mp4',\n    shots: ['/assets/portfolio-reviewed/sostoyanie/iphone-15-today.png', '/assets/portfolio-reviewed/sostoyanie/iphone-15-media.png', '/assets/portfolio-reviewed/sostoyanie/iphone-15-events.png'],"]
];
for(const [before,after] of targets){
 const n=text.split(before).length-1;
 assert.equal(n,1,'Expected one target for media swap, got '+n+': '+before);
 text=text.replace(before,after);
}
writeFileSync(src,text);
const evidence='assets/portfolio-media-evidence.js';
let provenance=readFileSync(evidence,'utf8');
assert.equal((provenance.match(/approvedForEmbedding:false/g)||[]).length,3);
for(const id of ['chatx','promomed']){
 const index=provenance.indexOf(id+':{');
 assert.ok(index>0,'Missing evidence section '+id);
 const end=provenance.indexOf('\n },',index);
 assert.ok(end>index);
 const source=provenance.slice(index,end);
 assert.ok(source.includes('approvedForEmbedding:false'));
 provenance=provenance.slice(0,index)+source.replace('approvedForEmbedding:false','approvedForEmbedding:true')+provenance.slice(end);
}
writeFileSync(evidence,provenance);
writeFileSync(join(root,'catalog.json'),JSON.stringify({
 status:'preview-reviewed',no_external_client_adoption_claim:true,
 disclaimer:'Demonstration captures and a public preview, not evidence of an external production deployment.',
 verified:retrieved
},null,2)+'\n');
console.log('MEDIA SOURCE SHA-256 VERIFIED: '+retrieved.map(x=>x.id+' '+x.files.length+' files').join('; '));
